<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?>
<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3 mb-0">Product Reviews</h1></div>
<form class="card border-0 p-3 mb-3" method="get"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="q" value="<?= esc($filters['q']) ?>" placeholder="Customer, product or order no"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected'] as $value): ?><option value="<?= $value ?>" <?= $filters['status']===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach ?></select></div><div class="col-md-2"><select class="form-select" name="rating"><option value="">All ratings</option><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>" <?= (int)$filters['rating']===$i?'selected':'' ?>><?= $i ?> stars</option><?php endfor ?></select></div><div class="col-md-3 d-flex gap-2"><button class="btn btn-success flex-grow-1">Filter</button><a class="btn btn-outline-secondary" href="<?= url_to('admin.reviews') ?>">Reset</a></div></div></form>
<div class="card border-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Review</th><th>Product / Order</th><th>Rating</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($reviews as $review): ?><tr><td><strong><?= esc($review['customer_name']) ?></strong><div class="text-muted small text-truncate" style="max-width:280px"><?= esc($review['review_text']) ?></div></td><td><?= esc($review['product_name']) ?><small class="d-block text-muted"><?= esc($review['order_no']) ?></small></td><td class="text-warning text-nowrap"><?= str_repeat('★',(int)$review['rating']) ?></td><td><span class="badge text-bg-<?= $review['status']==='approved'?'success':($review['status']==='rejected'?'danger':'warning') ?>"><?= esc($review['status']) ?></span></td><td class="text-nowrap"><?= esc(date('d M Y',strtotime($review['created_at']))) ?></td><td><a class="btn btn-sm btn-outline-success" href="<?= url_to('admin.reviews.show',$review['id']) ?>">View</a></td></tr><?php endforeach ?><?php if(!$reviews): ?><tr><td colspan="6" class="text-center text-muted py-5">No reviews found.</td></tr><?php endif ?></tbody></table></div></div><?= $pager->links() ?>
<?= $this->endSection() ?>
